INSERT INTO fms_receivable (
    receivable_id, tenant_id, source_type, source_id, customer_name,
    currency, amount, paid_amount, status, created_at, updated_at
)
VALUES (
    #{receivableId}, #{tenantId}, #{sourceType}, #{sourceId}, #{customerName},
    #{currency}, #{amount}, #{paidAmount}, #{status}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE fms_receivable
SET customer_name = #{customerName},
    currency = #{currency},
    amount = #{amount},
    paid_amount = #{paidAmount},
    status = #{status},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND receivable_id = #{receivableId}

mapper.select:
SELECT receivable_id, tenant_id, source_type, source_id, customer_name,
       currency, amount, paid_amount, status, created_at, updated_at
FROM fms_receivable
WHERE tenant_id = #{tenantId}
  AND receivable_id = #{receivableId}

SELECT receivable_id, tenant_id, source_type, source_id, customer_name,
       currency, amount, paid_amount, status, created_at, updated_at
FROM fms_receivable
WHERE tenant_id = #{tenantId}
  AND source_type = #{sourceType}
  AND source_id = #{sourceId}

