INSERT INTO fms_forex_rate (
    rate_id, tenant_id, from_currency, to_currency, rate,
    effective_date, source, created_at
)
VALUES (
    #{rateId}, #{tenantId}, #{fromCurrency}, #{toCurrency}, #{rate},
    #{effectiveDate}, #{source}, #{createdAt}
)

mapper.select:
SELECT rate_id, tenant_id, from_currency, to_currency, rate,
       effective_date, source, created_at
FROM fms_forex_rate
WHERE tenant_id = #{tenantId}
  AND from_currency = #{fromCurrency}
  AND to_currency = #{toCurrency}
  AND effective_date = #{effectiveDate}
  AND source = #{source}

SELECT rate_id, tenant_id, from_currency, to_currency, rate,
       effective_date, source, created_at
FROM fms_forex_rate
WHERE tenant_id = #{tenantId}
  AND from_currency = #{fromCurrency}
  AND to_currency = #{toCurrency}
ORDER BY effective_date DESC, created_at DESC, rate_id DESC
LIMIT 1

SELECT rate_id, tenant_id, from_currency, to_currency, rate,
       effective_date, source, created_at
FROM fms_forex_rate
WHERE tenant_id = #{tenantId}
  AND from_currency = #{fromCurrency}
  AND to_currency = #{toCurrency}
  AND effective_date <= #{effectiveDate}
ORDER BY effective_date DESC, created_at DESC, rate_id DESC
LIMIT 1

SELECT rate_id, tenant_id, from_currency, to_currency, rate,
       effective_date, source, created_at
FROM fms_forex_rate
WHERE tenant_id = #{tenantId}
  AND from_currency = #{fromCurrency}
  AND to_currency = #{toCurrency}
ORDER BY effective_date DESC, created_at DESC, rate_id DESC

